export const streamEmitter = new EventEmitter()
streamEmitter.setMaxListeners(30)
// An 'error' event with no listener would throw: the stream's problems are shown, never fatal.
streamEmitter.on('error', () => undefined)

/**
 * No data at all (not even Companies House's heartbeat) for this long means the
 * connection has died — as it does when the computer sleeps — so connect again.
 */
const SILENT_MS = 120_000

