  req.on('error', (err) => {
    if (state.active) {
      state.status = 'reconnecting'
      streamEmitter.emit('connectionError', ep, err.message)
      scheduleReconnect(apiKey, ep, state, retryDelay)
    }
  })
  // A connection gone quiet (sleep, a dropped network) is closed, which reconnects it from the last event.
  req.setTimeout(SILENT_MS, () => req.destroy(new Error('No data from Companies House for two minutes')))

  req.end()
  state.req = req
}
